      var bubble = document.getElementById("slider-value");
      var inputValue = document.getElementById("products_filter_average_rating").value;
      document.getElementById("slider-value").innerHTML = "<div class='value'>" + range.value + "</div>";
      var sliderDiv = document.querySelector(".filter-rating");
      bubble.style.marginLeft = "".concat(range.value * (sliderDiv.clientWidth - 22) / 100, "px");
